static int cmpLen(const void *a, const void *b) {
  const char *x = *(const char **)a, *y = *(const char **)b;
  int lx = strlen(x), ly = strlen(y);
  if (lx != ly) return ly - lx;
  return strcmp(x, y);
}

static int canForm(char *w, char **words, int wordsSize) {
  int n = strlen(w);
  int *dp = (int *)calloc(n + 1, sizeof(int));
  dp[0] = 1;
  for (int i = 1; i <= n; i++) {
    for (int j = 0; j < i; j++) {
      if (!dp[j]) continue;
      if (i == n && j == 0) continue;
      int len = i - j;
      for (int k = 0; k < wordsSize; k++) {
        if ((int)strlen(words[k]) == len && strncmp(words[k], w + j, len) == 0) {
          dp[i] = 1;
          break;
        }
      }
      if (dp[i]) break;
    }
  }
  int res = dp[n];
  free(dp);
  return res;
}

char *longestWord(char **words, int wordsSize) {
  qsort(words, wordsSize, sizeof(char *), cmpLen);
  for (int i = 0; i < wordsSize; i++) {
    if (canForm(words[i], words, wordsSize)) return words[i];
  }
  return "";
}

class Solution {
  bool canForm(const string &w, unordered_set<string> &dict) {
    int n = w.size();
    vector<bool> dp(n + 1, false);
    dp[0] = true;
    for (int i = 1; i <= n; i++) {
      for (int j = 0; j < i; j++) {
        if (!dp[j]) continue;
        if (i == n && j == 0) continue;
        if (dict.count(w.substr(j, i - j))) {
          dp[i] = true;
          break;
        }
      }
    }
    return dp[n];
  }

public:
  string longestWord(vector<string> &words) {
    unordered_set<string> dict(words.begin(), words.end());
    sort(words.begin(), words.end(), [](const string &a, const string &b) {
      if (a.size() != b.size()) return a.size() > b.size();
      return a < b;
    });
    for (const string &w : words) {
      if (canForm(w, dict)) return w;
    }
    return "";
  }
};

func longestWord(words []string) string {
	dict := map[string]bool{}
	for _, w := range words {
		dict[w] = true
	}
	sort.Slice(words, func(i, j int) bool {
		if len(words[i]) != len(words[j]) {
			return len(words[i]) > len(words[j])
		}
		return words[i] < words[j]
	})
	canForm := func(w string) bool {
		n := len(w)
		dp := make([]bool, n+1)
		dp[0] = true
		for i := 1; i <= n; i++ {
			for j := 0; j < i; j++ {
				if !dp[j] {
					continue
				}
				if i == n && j == 0 {
					continue
				}
				if dict[w[j:i]] {
					dp[i] = true
					break
				}
			}
		}
		return dp[n]
	}
	for _, w := range words {
		if canForm(w) {
			return w
		}
	}
	return ""
}

class Solution {
  private boolean canForm(String w, Set<String> dict) {
    int n = w.length();
    boolean[] dp = new boolean[n + 1];
    dp[0] = true;
    for (int i = 1; i <= n; i++) {
      for (int j = 0; j < i; j++) {
        if (!dp[j]) continue;
        if (i == n && j == 0) continue;
        if (dict.contains(w.substring(j, i))) {
          dp[i] = true;
          break;
        }
      }
    }
    return dp[n];
  }

  public String longestWord(String[] words) {
    Set<String> dict = new HashSet<>(Arrays.asList(words));
    Arrays.sort(words, (a, b) -> a.length() != b.length() ? b.length() - a.length() : a.compareTo(b));
    for (String w : words) {
      if (canForm(w, dict)) return w;
    }
    return "";
  }
}

class Solution:
    def longestWord(self, words: List[str]) -> str:
        word_set = set(words)
        words.sort(key=lambda w: (-len(w), w))

        def can_form(w: str) -> bool:
            n = len(w)
            dp = [False] * (n + 1)
            dp[0] = True
            for i in range(1, n + 1):
                for j in range(i):
                    if not dp[j]:
                        continue
                    if i == n and j == 0:
                        continue
                    if w[j:i] in word_set:
                        dp[i] = True
                        break
            return dp[n]

        for w in words:
            if can_form(w):
                return w
        return ""

impl Solution {
  pub fn longest_word(mut words: Vec<String>) -> String {
    let dict: HashSet<String> = words.iter().cloned().collect();
    words.sort_by(|a, b| {
      if a.len() != b.len() {
        b.len().cmp(&a.len())
      } else {
        a.cmp(b)
      }
    });
    let can_form = |w: &str| -> bool {
      let n = w.len();
      let mut dp = vec![false; n + 1];
      dp[0] = true;
      for i in 1..=n {
        for j in 0..i {
          if !dp[j] {
            continue;
          }
          if i == n && j == 0 {
            continue;
          }
          if dict.contains(&w[j..i]) {
            dp[i] = true;
            break;
          }
        }
      }
      dp[n]
    };
    for w in &words {
      if can_form(w) {
        return w.clone();
      }
    }
    String::new()
  }
}

const longestWord = (words: string[]): string => {
  const dict = new Set(words);
  words.sort((a, b) => (a.length !== b.length ? b.length - a.length : a.localeCompare(b)));
  const canForm = (w: string): boolean => {
    const n = w.length;
    const dp: boolean[] = new Array(n + 1).fill(false);
    dp[0] = true;
    for (let i = 1; i <= n; i++) {
      for (let j = 0; j < i; j++) {
        if (!dp[j]) continue;
        if (i === n && j === 0) continue;
        if (dict.has(w.slice(j, i))) {
          dp[i] = true;
          break;
        }
      }
    }
    return dp[n];
  };
  for (const w of words) {
    if (canForm(w)) return w;
  }
  return '';
};
